import React, { useState } from 'react';
import {
    Box,
    ThemeProvider,
    Container,
    Grid,
    CssBaseline,
    Fade,
    Tabs,
    Tab,
    Paper,
} from '@mui/material';
import theme from './theme';
import Header from './components/layout/Header';
import MetricCard from './components/common/MetricCard';
import StatusBadge from './components/common/StatusBadge';
import ForecastChart from './components/dashboard/ForecastChart';
import AlertPanel from './components/dashboard/AlertPanel';
import DataTable from './components/dashboard/DataTable';
import ModelMetrics from './components/dashboard/ModelMetrics';
import { ChartDataPoint } from './types';
import { formatNumber, formatPercentage } from './utils/formatters';
import { forecastData, recentForecasts } from './mocks/forecast.mock';

// Icons
import InventoryIcon from '@mui/icons-material/Inventory';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import AssessmentIcon from '@mui/icons-material/Assessment';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';

function App() {
    const [currentTab, setCurrentTab] = useState(0);
    const [lastUpdated] = useState(new Date().toLocaleTimeString());

    // Transform mock data to chart format
    const chartData: ChartDataPoint[] = forecastData.map((item) => ({
        date: item.date,
        predicted: item.forecast,
        actual: item.actual,
    }));

    // Transform recent forecasts to table format
    const tableData = recentForecasts.map((item) => ({
        timestamp: item.forecastDate,
        predicted_stockpile: item.generation,
        actual_stockpile: item.demand,
        station_name: item.powerStation,
    }));

    // Calculate summary metrics from mock data
    const currentStockpile = forecastData[forecastData.length - 1]?.actual || 0;
    const forecast7Days = forecastData.slice(-7).reduce((sum, item) => sum + item.forecast, 0) / 7;
    const forecast30Days = forecastData.reduce((sum, item) => sum + item.forecast, 0) / forecastData.length;
    const modelAccuracy = recentForecasts.reduce((sum, item) => sum + item.accuracy, 0) / recentForecasts.length / 100;

    // Mock alerts
    const mockAlerts = [
        {
            id: '1',
            severity: 'info' as const,
            message: 'System operating normally. All forecast models running smoothly.',
            timestamp: new Date().toISOString(),
        },
    ];

    const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
        setCurrentTab(newValue);
    };

    const handleRefresh = () => {
        window.location.reload();
    };

    return (
        <ThemeProvider theme={theme}>
            <CssBaseline />
            <Box sx={{ minHeight: '100vh', backgroundColor: 'background.default' }}>
                <Header
                    lastUpdated={lastUpdated}
                    onRefresh={handleRefresh}
                    loading={false}
                />

                <Container maxWidth="xl" sx={{ py: 4 }}>
                    <Fade in>
                        <Box>
                            {/* Navigation Tabs */}
                            <Paper
                                sx={{
                                    mb: 3,
                                    borderRadius: 3,
                                    overflow: 'hidden',
                                }}
                            >
                                <Tabs
                                    value={currentTab}
                                    onChange={handleTabChange}
                                    sx={{
                                        '& .MuiTab-root': {
                                            fontWeight: 700,
                                            fontSize: '1rem',
                                            textTransform: 'none',
                                            minHeight: 56,
                                            px: 4,
                                        },
                                    }}
                                >
                                    <Tab label="Dashboard" />
                                    <Tab label="Detailed Data" />
                                    <Tab label="Model Performance" />
                                </Tabs>
                            </Paper>

                            {/* Tab Panel 0: Dashboard Overview */}
                            {currentTab === 0 && (
                                <Grid container spacing={3}>
                                    {/* Top Metrics Row */}
                                    <Grid item xs={12} sm={6} md={3}>
                                        <MetricCard
                                            title="Current Generation"
                                            value={formatNumber(currentStockpile)}
                                            unit="MW"
                                            icon={<InventoryIcon sx={{ fontSize: 32 }} />}
                                            color="primary"
                                            trend="stable"
                                        />
                                    </Grid>

                                    <Grid item xs={12} sm={6} md={3}>
                                        <MetricCard
                                            title="7-Day Avg Forecast"
                                            value={formatNumber(forecast7Days)}
                                            unit="MW"
                                            icon={<CalendarTodayIcon sx={{ fontSize: 32 }} />}
                                            color="info"
                                        />
                                    </Grid>

                                    <Grid item xs={12} sm={6} md={3}>
                                        <MetricCard
                                            title="Overall Avg Forecast"
                                            value={formatNumber(forecast30Days)}
                                            unit="MW"
                                            icon={<TrendingUpIcon sx={{ fontSize: 32 }} />}
                                            color="success"
                                        />
                                    </Grid>

                                    <Grid item xs={12} sm={6} md={3}>
                                        <MetricCard
                                            title="Model Accuracy"
                                            value={formatPercentage(modelAccuracy)}
                                            unit=""
                                            icon={<AssessmentIcon sx={{ fontSize: 32 }} />}
                                            color="warning"
                                        />
                                    </Grid>

                                    {/* Status and Last Updated */}
                                    <Grid item xs={12}>
                                        <Box
                                            sx={{
                                                display: 'flex',
                                                justifyContent: 'space-between',
                                                alignItems: 'center',
                                                p: 2,
                                                backgroundColor: 'background.paper',
                                                borderRadius: 3,
                                                border: '1px solid',
                                                borderColor: 'divider',
                                            }}
                                        >
                                            <Box display="flex" alignItems="center" gap={2}>
                                                <Box sx={{ color: 'text.secondary', fontWeight: 600 }}>
                                                    System Status:
                                                </Box>
                                                <StatusBadge
                                                    status="Normal"
                                                    size="medium"
                                                />
                                            </Box>
                                            <Box sx={{ color: 'text.secondary', fontSize: '0.875rem', fontWeight: 600 }}>
                                                Last updated: {lastUpdated}
                                            </Box>
                                        </Box>
                                    </Grid>

                                    {/* Main Chart */}
                                    <Grid item xs={12} lg={8}>
                                        <ForecastChart
                                            data={chartData}
                                            loading={false}
                                            showConfidenceInterval={false}
                                            title="Generation Forecast Trend"
                                        />
                                    </Grid>

                                    {/* Alerts Panel */}
                                    <Grid item xs={12} lg={4}>
                                        <AlertPanel
                                            alerts={mockAlerts}
                                            loading={false}
                                        />
                                    </Grid>
                                </Grid>
                            )}

                            {/* Tab Panel 1: Detailed Data */}
                            {currentTab === 1 && (
                                <Grid container spacing={3}>
                                    <Grid item xs={12}>
                                        <DataTable
                                            data={tableData}
                                            loading={false}
                                            title="Recent Forecast Data"
                                        />
                                    </Grid>
                                </Grid>
                            )}

                            {/* Tab Panel 2: Model Performance */}
                            {currentTab === 2 && (
                                <Grid container spacing={3}>
                                    <Grid item xs={12} md={6}>
                                        <ModelMetrics
                                            metrics={{
                                                accuracy: modelAccuracy,
                                                mae: 0.05,
                                                rmse: 0.08,
                                                r2_score: 0.92,
                                            }}
                                            loading={false}
                                        />
                                    </Grid>
                                    <Grid item xs={12} md={6}>
                                        <ForecastChart
                                            data={chartData}
                                            title="Prediction Accuracy Over Time"
                                            showConfidenceInterval={false}
                                        />
                                    </Grid>
                                </Grid>
                            )}
                        </Box>
                    </Fade>
                </Container>
            </Box>
        </ThemeProvider>
    );
}

export default App;
